pragma solidity ^0.8.20;

// Synthetic share vault for the offline value_out / supply end-to-end proof.
// Deliberately built with the two shapes that reached production undetected:
// an ``unchecked`` burn (so an over-seeded holder wraps totalSupply past zero)
// and a payout guarded on a non-zero amount.
contract SeedVault {
    address public owner;
    address public immutable treasury;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) private _allowances;

    event Transfer(address indexed from, address indexed to, uint256 value);

    constructor(address treasury_) {
        owner = msg.sender;
        treasury = treasury_;
    }

    function allowance(address o, address s) external view returns (uint256) {
        return _allowances[o][s];
    }

    function approve(address s, uint256 a) external returns (bool) {
        _allowances[msg.sender][s] = a;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    // The universal _burn idiom. With a holder balance seeded ABOVE totalSupply
    // this wraps past zero and totalSupply reads as ~2**256 afterwards.
    function exit(uint256 shares) external {
        balanceOf[msg.sender] -= shares;
        unchecked {
            totalSupply -= shares;
        }
        emit Transfer(msg.sender, address(0), shares);
    }

    function mintTo(address to, uint256 shares) external {
        require(msg.sender == owner, "not owner");
        totalSupply += shares;
        balanceOf[to] += shares;
        emit Transfer(address(0), to, shares);
    }

    // Pays the immutable treasury, and only when the amount is non-zero.
    function sweepToTreasury(uint256 amount) external {
        if (amount > 0) {
            balanceOf[address(this)] -= amount;
            balanceOf[treasury] += amount;
            emit Transfer(address(this), treasury, amount);
        }
    }
}
